import{z as l,x as i,o as A,c as D,q as B,j as n,D as e,d as r,s as o,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Transformers generate 走读","description":"","frontmatter":{"title":"Transformers generate 走读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-hf-generate-walkthrough.md","filePath":"llm/fw-hf-generate-walkthrough.md","lastUpdated":1791413859000}'),p={name:"llm/fw-hf-generate-walkthrough.md"};function d(m,E,h,g,F,f){const t=i("Mermaid");return A(),D("div",null,[E[2]||(E[2]=B('<h1 id="transformers-generate-走读" tabindex="-1">Transformers generate 走读 <a class="header-anchor" href="#transformers-generate-走读" aria-label="Permalink to &quot;Transformers generate 走读&quot;">​</a></h1><div class="epigraph"><p>最被广泛阅读的推理代码是那个不调度的循环：一代人关于解码的知识，都挂在这棵处理器子类树上。</p><footer>—— 据 Hugging Face Transformers 文档与 GenerationMixin 源码整理</footer></div><p><a href="/llm/fw-mlc-walkthrough">上一课</a>的执行体沉进编译产物，Transformers 走另一极：没有调度器、没有服务语义，只有一个调用者亲手喂批的生成循环。停止语义已写过——结束符、停用串与长度预算三分，见<a href="/llm/stop-sequences">停用词与 stop sequences</a>；投机解码的验证循环也已写过。本课进仓库读 generate 这条主干，讲它的分层与数据结构，以仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>引擎走读完，回到这个库会产生错觉：同样的「采样、判断停、拼输入」循环，凭什么单开一课？差别不在循环，在<strong>谁管批</strong>。引擎里批由调度器按迭代组出、成员按步进出；这里批是调用方给死的：一次调用、一个填好的张量批、一起进一起出，没有准入、没有抢占、没有 KV 会计。走读的问题于是是：在「不调度」这个约束下，代码把全部设计预算花在了哪里，又因为不调度付出了什么。</p><p><span class="marginnote">直觉类比「缓存对象」：模型每生成一个字，都要回看前面所有字算注意力。缓存对象就是把前面每层的「中间算力」存起来别重复算的本子——像读长文时夹的书签，翻到第 100 页不用从第 1 页重读。这代代码做的事，是把这块「本子」从一个裸张量升级成会自我管理（预分配、卸载、分页）的对象族。</span></p><h3 id="主干的分层" tabindex="-1">主干的分层 <a class="header-anchor" href="#主干的分层" aria-label="Permalink to &quot;主干的分层&quot;">​</a></h3><p>generate 挂在模型类上，分四层。准备层：校验生成配置，补齐默认值，把输入整理成张量批。循环层：按策略分派到贪心、采样、束搜索或带草稿的验证循环，骨架一致——一次前向、处理 logits、选 token、判停。处理层是它的灵魂：对 logits 逐步施改的处理器队列，与判断结束的判停器队列，都是「小对象按序执行」的管道。缓存层：过去键值被抽成缓存对象族，从逐层追加的动态缓存，到为编译与投机预留的静态预分配缓存，再到分层卸载的变体——缓存对象是这一代代码里最重要的抽象迁移。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沿一步走：前向吃输入与缓存，吐 logits；处理器队列按登记顺序收窄分布——温度、top-k、top-p、重复惩罚各是一个对象，<strong>顺序即语义</strong>，调换两项会得到另一种分布；采样选出 token；判停器逐序列检查结束符与长度，结束的序列打上完成标记但留在批里，因为同批其余序列还在跑；流式回调把增量交给调用方。这最后一条正是无调度的代价：先结束的序列占着批位置空转到全批结束，引擎用迭代级准入消掉的空转，这里原样保留。</p><p><span class="marginnote">术语翻译：logits 就是模型对词表里每个词打出的原始分数（几万个数），还没变成概率。top-k 是「只留分数前 k 名」，top-p 是「从高到低累加概率、攒够 p 就截断」。两者都是收窄分布的漏斗——漏斗的先后顺序不同，最后剩下的候选集就不同。</span></p>',11)),(A(),n(s,null,{default:e(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E7%94%9F%E6%88%90%E9%85%8D%E7%BD%AE%EF%BC%9A%E9%BB%98%E8%AE%A4%E5%80%BC%E4%B8%8E%E6%A0%A1%E9%AA%8C%22%5D%20--%3E%20LOOP%5B%22%E7%AD%96%E7%95%A5%E5%BE%AA%E7%8E%AF%EF%BC%9A%E8%B4%AA%E5%BF%83%20%2F%20%E9%87%87%E6%A0%B7%20%2F%20%E6%9D%9F%E6%90%9C%E7%B4%A2%22%5D%0A%20%20LOOP%20--%3E%20FWD%5B%22%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%EF%BC%9A%E8%BE%93%E5%85%A5%20%2B%20%E7%BC%93%E5%AD%98%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20FWD%20--%3E%20PROC%5B%22logits%20%E5%A4%84%E7%90%86%E5%99%A8%E9%98%9F%E5%88%97%EF%BC%9A%E9%A1%BA%E5%BA%8F%E5%8D%B3%E8%AF%AD%E4%B9%89%22%5D%0A%20%20PROC%20--%3E%20SAMP%5B%22%E9%87%87%E6%A0%B7%20token%22%5D%0A%20%20SAMP%20--%3E%20STOP%5B%22%E5%88%A4%E5%81%9C%E5%99%A8%E9%98%9F%E5%88%97%EF%BC%9A%E9%80%90%E5%BA%8F%E5%88%97%E6%A0%87%E8%AE%B0%22%5D%0A%20%20STOP%20--%3E%7C%E6%9C%AA%E5%85%A8%E5%81%9C%7C%20FWD%0A%20%20STOP%20--%3E%7C%E5%85%A8%E5%81%9C%7C%20OUT%5B%22%E8%A7%A3%E7%A0%81%E8%BF%94%E5%9B%9E%22%5D%0A%20%20FWD%20--%3E%20CACHE%5B%22%E7%BC%93%E5%AD%98%E5%AF%B9%E8%B1%A1%EF%BC%9A%E5%8A%A8%E6%80%81%20%2F%20%E9%9D%99%E6%80%81%20%2F%20%E5%8D%B8%E8%BD%BD%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"处理器队列的顺序在文档里是推荐而非强制，复现论文采样设置时要逐项核对登记次序：温度在 top-p 之前或之后，支撑集并不相同——这是这个库最常见的研究复现偏差来源之一。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"为什么它仍是默认载体：每个研究想法都能落成一个处理器或判停器子类，几行代码挂进队列就能出现在下一版论文基线里；循环本身一眼可读，是教学与复现的最小公共分母。为什么它成不了服务：批是调用方的责任，就没有内存会计与准入；缓存对象再精巧，也只是会话内优化，没有跨请求共享与回收；束搜索这类批内分支让「一步的工作量」随序列数变化，调度器更无从谈起。前几课的框架正是对着这两个缺口逐条补齐：准入与记账补在调度器，共享补在缓存抽象。",-1)),(A(),n(s,null,{default:e(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20HF%5B%22Transformers%20generate%3A%20%E6%89%B9%E7%94%B1%E8%B0%83%E7%94%A8%E6%96%B9%E7%BB%99%E6%AD%BB%22%5D%0A%20%20%20%20A1%5B%22%E6%89%B9%204%20%E6%9D%A1%E4%B8%80%E8%B5%B7%E8%BF%9B%22%5D%20--%3E%20A2%5B%22%E5%BA%8F%E5%88%97%202%20%E5%9C%A8%E7%AC%AC%2012%20%E6%AD%A5%E7%BB%93%E6%9D%9F%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E5%BA%8F%E5%88%97%202%20%E7%BB%A7%E7%BB%AD%E5%8D%A0%E4%BD%8D%E7%A9%BA%E8%BD%AC%22%5D%0A%20%20%20%20A3%20--%3E%20A4%5B%22%E7%AC%AC%2060%20%E6%AD%A5%E5%85%A8%E5%81%9C%EF%BC%8C%E6%89%B9%E6%89%8D%E9%80%80%E5%87%BA%22%5D%0A%20%20end%0A%20%20subgraph%20ENG%5B%22%E6%9C%8D%E5%8A%A1%E5%BC%95%E6%93%8E%3A%20%E8%B0%83%E5%BA%A6%E5%99%A8%E7%AE%A1%E6%89%B9%22%5D%0A%20%20%20%20E1%5B%22%E8%BF%AD%E4%BB%A3%E7%BA%A7%E5%87%86%E5%85%A5%EF%BC%9A%E6%89%B9%E6%88%90%E5%91%98%E6%AF%8F%E6%AD%A5%E5%8F%AF%E6%8D%A2%22%5D%20--%3E%20E2%5B%22%E5%BA%8F%E5%88%97%202%20%E7%BB%93%E6%9D%9F%E5%8D%B3%E9%80%80%E5%87%BA%22%5D%0A%20%20%20%20E2%20--%3E%20E3%5B%22%E7%A9%BA%E5%87%BA%E7%9A%84%E6%A7%BD%E4%BD%8D%E7%AB%8B%E5%88%BB%E6%94%BE%E8%BF%9B%E6%96%B0%E8%AF%B7%E6%B1%82%22%5D%0A%20%20%20%20E3%20--%3E%20E1%0A%20%20end%0A%20%20HF%20--%20%22%E5%90%9E%E5%90%90%E5%B7%AE%E8%B7%9D%E6%9D%A5%E6%BA%90%22%20--%3E%20ENG%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对照要公平：它对标的是「一次调用内的正确解码」，不是吞吐；拿它和引擎比每秒 token 数是口径错误。结束语义与流式挂起的细节在停止课已钉，本课不重述；束搜索的内部重排、草稿验证的接受判据各有专课。类名与方法名近年持续重构，以仓库当时状态为准。本课程用它收拢主流框架单元：从这条无调度的基线出发，vLLM、SGLang、TensorRT-LLM、llama.cpp、MLC 各自的选择才显出形状。</p><p><span class="marginnote">「空转」为什么是真金白银的浪费：假设批里 4 条，一条 10 步就写完、另外三条要写 500 步，那第 11 步到第 500 步里，那条早结束的序列仍在每次前向里占一个批位、占一份显存和算力，只是产出永远被丢弃。批越大越常见，这也是引擎做迭代级调度的第一动机。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>generate 是「不调度」的基线：批由调用方给死，同进同出，无准入、无 KV 会计。</li><li>主干分四层：配置准备、策略循环、处理器与判停器管道、缓存对象族。</li><li>处理器队列顺序即语义，复现偏差常出在登记次序。</li><li>结束序列留在批里空转，是引擎迭代级调度所消掉的实物成本。</li><li>它的价值是可读与可扩展，价值边界就是不服务；读它为了定坐标，不为了上线。</li><li>出处：Hugging Face Transformers 文档与 GenerationMixin 源码，按源码结构整理。</li></ul>',5))])}const T=l(p,[["render",d]]);export{u as __pageData,T as default};
